'use client';
import {useEffect,useRef,useState} from 'react';
import {useClientReady} from '@/lib/client-ready';
import {cents,formText,hotelRpc,usd,type Booking,type HotelWorkspace} from '@/lib/pilot';
import {definitiveBookingRejection} from '@/lib/pending-booking';
import {afterDays} from '@/lib/rates';
type Command={p_request:string;p_expected_version:number;p_departure:string;p_accommodation_minor:number;p_taxes_minor:number;p_reason:string};
type Result={reservation:Booking;replayed:boolean;previous_departure:string;business_date:string;overdue_resolved:boolean;folio_opening_retained:boolean;financial_reconciliation_required:boolean;pricing_reconciliation_required?:boolean;hotel_fees_retained?:boolean};
type Props={actor:string;tenant:string;property:string;booking:Booking;businessDate:string;onBusyChange:(busy:boolean)=>void;onSaved:(result:Result)=>Promise<void>};
export function ExtendStay(props:Props){const ready=useClientReady();return ready?<ExtensionForm {...props}/>:<p>Loading saved requests…</p>}
function ExtensionForm({actor,tenant,property,booking,businessDate,onBusyChange,onSaved}:Props){
 const storageKey='iratepilot-pms-pending-extension:'+actor+':'+tenant+':'+property+':'+booking.id;
 const [restored]=useState(()=>{try{const raw=sessionStorage.getItem(storageKey);if(raw===null)return {pending:null,error:''};const c=JSON.parse(raw);if(!c||typeof c.p_request!=='string'||!Number.isSafeInteger(c.p_expected_version)||c.p_expected_version<1||typeof c.p_departure!=='string'||typeof c.p_reason!=='string'||![c.p_accommodation_minor,c.p_taxes_minor].every(n=>Number.isSafeInteger(n)&&n>=0))throw Error('Invalid request');return {pending:c as Command,error:''}}catch{return {pending:null,error:'The saved extension request could not be read. Reconcile this stay before making further changes.'}}});
 const [pending,setPending]=useState<Command|null>(restored.pending),[current,setCurrent]=useState(booking),[date,setDate]=useState(businessDate),[revision,setRevision]=useState(0),[fresh,setFresh]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false);const lock=useRef(false),alive=useRef(true);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;if(lock.current)onBusyChange(false)}},[onBusyChange]);
 async function run(fn:()=>Promise<void>){if(lock.current)return;lock.current=true;setBusy(true);onBusyChange(true);setError('');try{await fn()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to update stay.')}finally{lock.current=false;if(alive.current){setBusy(false);onBusyChange(false)}}}
 async function refresh(){setFresh(false);const workspace=await hotelRpc<HotelWorkspace>('workspace',{p_tenant:tenant,p_property:property});if(!alive.current)return;const latest=workspace.reservations.find(r=>r.id===booking.id);if(!latest)throw Error('Reservation is no longer available.');setCurrent(latest);setDate(workspace.business_date);setRevision(n=>n+1);setFresh(true)}
 async function save(command:Command){
  let result:Result;
  try{result=await hotelRpc<Result>('extend_stay',{p_tenant:tenant,p_property:property,p_reservation:booking.id,...command})}
  catch(e){if(alive.current&&definitiveBookingRejection(e)){sessionStorage.removeItem(storageKey);setPending(null);setFresh(false);throw e}throw Error('The extension result is uncertain. Retry the preserved request below to confirm it.')}
  if(alive.current){sessionStorage.removeItem(storageKey);setPending(null);await onSaved(result)}
 }
 const eligible=current.status==='In house'&&current.source!=='iratepilot-ota';
 const earliest=afterDays((current.departure??date)>date?current.departure!:date,1);
 return <>{error&&<div className="pilot-error" role="alert">{error}</div>}{restored.error?<div className="pilot-error" role="alert">{restored.error}</div>:pending?<section><h3>Confirm saved extension</h3><p>New departure: <b>{pending.p_departure}</b></p><p>Revised accommodation + tax subtotal: <b>{usd(pending.p_accommodation_minor+pending.p_taxes_minor)}</b></p>{(current.hotel_fees_minor??0)>0&&<p>Retained hotel fees: {usd(current.hotel_fees_minor)} in addition to this subtotal.</p>}<p>{pending.p_reason}</p><button className="primary" disabled={busy} onClick={()=>void run(()=>save(pending))}>Retry this exact extension</button></section>:<><button className="text-button" disabled={busy} onClick={()=>void run(refresh)}>Reload current stay and discard edits</button>{!fresh?<p>Reload the current stay before preparing another extension.</p>:!eligible?<p>This stay cannot be extended here. OTA changes must be made at their source.</p>:<form key={current.source_version+'/'+revision} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void run(async()=>{const command:Command={p_request:crypto.randomUUID(),p_expected_version:current.source_version,p_departure:formText(f,'departure'),p_accommodation_minor:cents(f.get('amount')),p_taxes_minor:cents(f.get('taxes')),p_reason:formText(f,'reason').trim()};sessionStorage.setItem(storageKey,JSON.stringify(command));setPending(command);await save(command)})}}><p>{current.guest_name} · current departure {current.departure}. The guest keeps the same room.</p><label className="field">New departure<input name="departure" type="date" min={earliest} max={current.arrival?afterDays(current.arrival,30):undefined} required disabled={busy}/></label><div className="form-grid"><label className="field">New total accommodation (USD)<input name="amount" type="number" min="0" step="0.01" defaultValue={((current.accommodation_minor??0)/100).toFixed(2)} required disabled={busy}/></label><label className="field">New total taxes (USD)<input name="taxes" type="number" min="0" step="0.01" defaultValue={((current.taxes_minor??0)/100).toFixed(2)} required disabled={busy}/></label></div><label className="field">Reason<textarea name="reason" minLength={4} maxLength={500} required disabled={busy}/></label>{(current.hotel_fees_minor??0)>0&&<p className="pilot-notice">Hotel fees of {usd(current.hotel_fees_minor)} are retained in addition to the accommodation and taxes entered here. Extra nights do not automatically add hotel fees; review the folio and record any needed adjustment.</p>}<p>Enter the full revised accommodation and taxes, including nights already booked. Posted folio entries stay unchanged and may need an adjustment. No payment is collected.</p><label className="pilot-check"><input type="checkbox" required disabled={busy}/>I reviewed the departure and full stay charges.</label><button className="primary" disabled={busy}>Extend stay</button></form>}</>}</>;
}
